#include "zebra_puzzle.h"

#include <algorithm>
#include <array>

namespace zebra_puzzle {

namespace {

enum Color { RED, GREEN, IVORY, YELLOW, BLUE };
enum Nat { ENGLISHMAN, SPANIARD, UKRAINIAN, NORWEGIAN, JAPANESE };
enum Bev { COFFEE, TEA, MILK, ORANGE_JUICE, WATER };
enum Hobby { DANCING, PAINTING, READING, FOOTBALL, CHESS };
enum Pet { DOG, SNAIL, FOX, HORSE, ZEBRA };

const char* NAT_NAMES[] = {"Englishman", "Spaniard", "Ukrainian", "Norwegian", "Japanese"};

}  // namespace

Solution solve() {
    std::array<int, 5> color{0, 1, 2, 3, 4};
    do {
        // 10 & 15: Norwegian in house 0, next to blue => house 1 is blue.
        if (color[1] != BLUE) continue;

        // 6: green house immediately right of ivory house.
        int green = -1, ivory = -1;
        for (int i = 0; i < 5; ++i) {
            if (color[i] == GREEN) green = i;
            if (color[i] == IVORY) ivory = i;
        }
        if (green != ivory + 1) continue;

        std::array<int, 5> nat{0, 1, 2, 3, 4};
        do {
            // 10: Norwegian lives in the first house.
            if (nat[0] != NORWEGIAN) continue;

            // 2: Englishman lives in the red house.
            bool ok = true;
            for (int i = 0; i < 5; ++i)
                if (nat[i] == ENGLISHMAN && color[i] != RED) ok = false;
            if (!ok) continue;

            std::array<int, 5> bev{0, 1, 2, 3, 4};
            do {
                // 9: middle house drinks milk.
                if (bev[2] != MILK) continue;

                ok = true;
                for (int i = 0; i < 5; ++i) {
                    // 4: green house drinks coffee.
                    if (color[i] == GREEN && bev[i] != COFFEE) ok = false;
                    // 5: Ukrainian drinks tea.
                    if (nat[i] == UKRAINIAN && bev[i] != TEA) ok = false;
                }
                if (!ok) continue;

                std::array<int, 5> hobby{0, 1, 2, 3, 4};
                do {
                    ok = true;
                    for (int i = 0; i < 5; ++i) {
                        // 8: yellow house is the painter's.
                        if (color[i] == YELLOW && hobby[i] != PAINTING) ok = false;
                        // 13: football player drinks orange juice.
                        if (hobby[i] == FOOTBALL && bev[i] != ORANGE_JUICE) ok = false;
                        // 14: Japanese person plays chess.
                        if (nat[i] == JAPANESE && hobby[i] != CHESS) ok = false;
                    }
                    if (!ok) continue;

                    std::array<int, 5> pet{0, 1, 2, 3, 4};
                    do {
                        ok = true;
                        for (int i = 0; i < 5; ++i) {
                            // 3: Spaniard owns the dog.
                            if (nat[i] == SPANIARD && pet[i] != DOG) ok = false;
                            // 7: snail owner goes dancing.
                            if (hobby[i] == DANCING && pet[i] != SNAIL) ok = false;
                        }
                        if (!ok) continue;

                        int fox = -1, horse = -1, reader = -1, painter = -1;
                        for (int i = 0; i < 5; ++i) {
                            if (pet[i] == FOX) fox = i;
                            if (pet[i] == HORSE) horse = i;
                            if (hobby[i] == READING) reader = i;
                            if (hobby[i] == PAINTING) painter = i;
                        }
                        // 11: reader next to fox.
                        int fd = fox - reader;
                        if (fd != 1 && fd != -1) continue;
                        // 12: painter next to horse.
                        int hd = horse - painter;
                        if (hd != 1 && hd != -1) continue;

                        int water = -1, zebra = -1;
                        for (int i = 0; i < 5; ++i) {
                            if (bev[i] == WATER) water = i;
                            if (pet[i] == ZEBRA) zebra = i;
                        }

                        Solution s;
                        s.drinksWater = NAT_NAMES[nat[water]];
                        s.ownsZebra = NAT_NAMES[nat[zebra]];
                        return s;
                    } while (std::next_permutation(pet.begin(), pet.end()));
                } while (std::next_permutation(hobby.begin(), hobby.end()));
            } while (std::next_permutation(bev.begin(), bev.end()));
        } while (std::next_permutation(nat.begin(), nat.end()));
    } while (std::next_permutation(color.begin(), color.end()));

    return Solution{};
}

}  // namespace zebra_puzzle

